<script>
(()=>{const t=window.ccsText||function(v){return v;};document.querySelectorAll('[data-serial-entry]').forEach(root=>{
const source=root.querySelector('[data-serial-canonical]'),lines=root.querySelector('[data-serial-lines]'),quantity=root.querySelector('[data-serial-count]');
function sync(){const inputs=[...lines.querySelectorAll('input')],values=inputs.map(input=>input.value.trim()).filter(Boolean);source.value=values.join('\n');quantity.value=values.length;const seen=new Set();inputs.forEach((input,index)=>{input.required=root.dataset.required==='1'&&index===0;input.setCustomValidity('');const key=input.value.trim().toUpperCase();if(key&&seen.has(key))input.setCustomValidity(t('This serial appears more than once.'));if(key)seen.add(key);});[...lines.children].forEach((row,i)=>row.querySelector('span').textContent=i+1);}
function add(value=''){if(lines.children.length>=200)return;const row=document.createElement('div');row.className='serial-line';const index=document.createElement('span'),input=document.createElement('input'),remove=document.createElement('button');input.type='text';input.maxLength=100;input.autocomplete='off';input.value=value;input.setAttribute('aria-label',t('Actual Serial Number'));remove.type='button';remove.className='secondary';remove.textContent=t('Remove');remove.addEventListener('click',()=>{row.remove();if(!lines.children.length)add();sync();});input.addEventListener('input',sync);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();lines.lastElementChild.querySelector('input').focus();}});row.append(index,input,remove);lines.append(row);sync();}
const initial=source.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);for(const value of initial)add(value);if(!initial.length)add();root.querySelector('[data-serial-add]').addEventListener('click',()=>{add();lines.lastElementChild.querySelector('input').focus();});root.closest('form').addEventListener('submit',sync);
});})();
</script>
